body:
reg initialized = 1'b0;
reg last_reset = 1'b0;
reg [4:0] count = 5'd0;
reg [3:0] head = 4'd0;
reg [3:0] tail = 4'd0;
reg [7:0] words [0:15];
wire take_read = i_rd && (count != 5'd0);
wire take_write = i_wr && (count < 5'd16);

always @(posedge i_clk) begin
    last_reset <= i_reset;
    if (i_reset) begin
        initialized <= 1'b1;
        count <= 5'd0;
        head <= 4'd0;
        tail <= 4'd0;
    end else if (initialized) begin
        if (take_write) begin
            words[tail] <= i_data;
            tail <= tail + 4'd1;
        end
        if (take_read)
            head <= head + 4'd1;
        case ({take_write, take_read})
            2'b10: count <= count + 5'd1;
            2'b01: count <= count - 5'd1;
            default: count <= count;
        endcase
    end
end

assign active[0] = initialized;
assign ok[0] = (o_fill === count);
assign active[1] = initialized;
assign ok[1] = (o_full === (count == 5'd16));
assign active[2] = initialized;
assign ok[2] = (o_empty === (count == 5'd0));
assign active[3] = initialized && (count != 5'd0);
assign ok[3] = (o_data === words[head]);
assign active[4] = initialized && last_reset;
assign ok[4] = (o_fill === 5'd0) && (o_full === 1'b0) && (o_empty === 1'b1);
assign active[5] = initialized;
assign ok[5] = ((o_fill <= 5'd16) === 1'b1)
            && (o_full === (o_fill == 5'd16))
            && (o_empty === (o_fill == 5'd0));
